import {createClient} from './vendor/supabase.js';
import {esc} from './organiser-utils.js';
import {safeMediaURL,uploadPhoto} from './media-rules.js';
const roster='elan_oc_roster',access='elan_oc_access',tasks='elan_oc_tasks',states=['Open','In progress','Done'];
const data=async q=>{const r=await q;if(r.error)throw r.error;return r.data;};
const input=(n,label,options='')=>'<label>'+label+'<input name="'+n+'" '+options+'></label>';
const field=(f,k)=>String(new FormData(f).get(k)||'').trim();
function submit(f,fn){f.onsubmit=async e=>{e.preventDefault();if(f.inert||!f.reportValidity())return;f.inert=true;const msg=f.querySelector('[role=status]');try{msg.textContent='Saving…';await fn(f);msg.textContent='Saved.';}catch(err){msg.textContent=err.message||'Could not save. Try again.';}finally{f.inert=false;}};}
function rowsByDepartment(rows){const map=new Map();for(const r of rows){if(!map.has(r.department))map.set(r.department,[]);map.get(r.department).push(r);}return map;}
export async function startOC(){
 const config=await fetch('/assets/public-config.json').then(r=>r.json()),sb=createClient(config.supabaseUrl,config.publishableKey);
 const dir=document.querySelector('#oc-directory');if(dir){const rows=await data(sb.from(roster).select('name,role,department,bio,portrait,sort_order').eq('published',true).order('sort_order').order('name'));dir.innerHTML=[...rowsByDepartment(rows)].map(([dep,list])=>'<section class="oc-dept"><h3>'+esc(dep)+'</h3><div class="oc-cards">'+list.map(r=>'<article class="oc-person">'+(safeMediaURL(r.portrait,config.supabaseUrl)?'<img src="'+esc(r.portrait)+'" alt="'+esc(r.name)+'" loading="lazy">':'<div class="oc-initial" aria-hidden="true">'+esc(r.name.split(/\s+/).slice(0,2).map(x=>x[0]).join(''))+'</div>')+'<h4>'+esc(r.name)+'</h4><p>'+esc(r.role)+'</p>'+(r.bio?'<p>'+esc(r.bio)+'</p>':'')+'</article>').join('')+'</div></section>').join('')||'Committee profiles will appear here when published.';return;}
}
export async function adminOC({sb,api,config,host,isCurrent}){
 const [people,users,jobs]=await Promise.all([data(sb.from(roster).select('*').order('sort_order').order('name')),data(sb.from(access).select('*').order('label')),data(sb.from(tasks).select('*').order('title'))]);if(!isCurrent())return;
 const deps=[...new Set([...people,...users].map(r=>r.department))];const formEnd='<p role="status"></p></form>';
 host.innerHTML='<section class="app-card"><p class="app-badge">COMMITTEE / ADMIN</p><h2>Committee & access</h2><p>2026 profiles are public only when published. 2027 applications arrive in Organiser inbox as volunteer enquiries. Workspace access is granted separately.</p><datalist id="oc-deps">'+deps.map(d=>'<option value="'+esc(d)+'">').join('')+'</datalist><section class="oc-panel"><h3>2026 directory</h3><label>Member<select id="oc-picker"><option value="">Add a member</option>'+people.map(p=>'<option value="'+p.id+'">'+esc(p.name)+' · '+esc(p.department)+(p.published?'':' (draft)')+'</option>').join('')+'</select></label><form id="oc-profile">'+input('name','Full name','required maxlength="150"')+input('department','Department (choose or enter a new one)','required list="oc-deps" maxlength="90"')+input('role','Committee role','required maxlength="150"')+'<label>About this member (optional)<textarea name="bio" maxlength="1500"></textarea></label>'+input('photo','Portrait (optional; JPEG, PNG or WebP)','type="file" accept="image/jpeg,image/png,image/webp"')+input('sort_order','Display order','type="number" value="50" required')+'<label><span><input name="published" type="checkbox"> Publish on the 2026 directory</span></label><button>Save member</button>'+formEnd+'</section><section class="oc-panel"><h3>2027 organiser access</h3><p>Grant access only after selection. Updating an existing account replaces its department and role. Members see their own tasks; leads see the department’s tasks.</p><form id="oc-grant">'+input('email','Verified account email','type="email" required')+input('department','Department','list="oc-deps" maxlength="90" required')+'<label>Permission<select name="role"><option value="member">Member</option><option value="lead">Department lead</option></select></label><button>Save assignment</button>'+formEnd+users.map(u=>'<p>'+esc(u.label)+' · '+esc(u.department)+' · '+esc(u.role)+' <button data-revoke="'+u.user_id+'">Revoke OC access</button></p>').join('')+'</section><section class="oc-panel"><h3>Assign a responsibility</h3><form id="oc-task"><label>Organiser<select name="user_id" required><option value="">Choose organiser</option>'+users.map(u=>'<option value="'+u.user_id+'">'+esc(u.label+' · '+u.department)+'</option>').join('')+'</select></label>'+input('title','Task title','required maxlength="200"')+'<label>Brief<textarea name="brief" maxlength="2500"></textarea></label><button>Assign task</button>'+formEnd+jobs.map(j=>'<p>'+esc(j.title)+' · '+esc(j.department)+' · '+esc(users.find(u=>u.user_id===j.assigned_to)?.label||'Former organiser')+' · '+esc(j.status)+'</p>').join('')+'</section><p role="status" id="oc-message"></p></section>';
 const publish=document.createElement('section');publish.className='oc-panel';publish.innerHTML='<h3>Organiser panel briefings & resources</h3><p>Publish information for a department and permission level.</p><div></div>';host.querySelector('.app-card').append(publish);
 const {composer}=await import('./team-panel.js');composer(publish.querySelector('div'),{sb,admin:true,after:async()=>{}});
 const {toolNames}=await import('./department-tools.js');const modules=await data(sb.from('elan_oc_modules').select('*').order('department'));if(!isCurrent())return;
 const setup=document.createElement('section');setup.className='oc-panel';setup.innerHTML='<h3>Department tools</h3><p>Assign organisers to the exact department name below to open its register. Each department keeps its own records.</p><ul>'+modules.map(m=>'<li>'+esc(m.department)+' · '+esc(toolNames[m.tool])+'</li>').join('')+'</ul><form><label>Additional department name<input name="department" maxlength="90" required></label><label>Register type<select name="tool">'+Object.entries(toolNames).map(([k,l])=>'<option value="'+k+'">'+esc(l)+'</option>').join('')+'</select></label><button>Enable department tools</button><p role="status"></p></form>';host.querySelector('.app-card').append(setup);submit(setup.querySelector('form'),async f=>{await data(sb.from('elan_oc_modules').insert({department:field(f,'department'),tool:field(f,'tool')}));await refresh('Department tools enabled.');});for(const m of modules){if(!deps.includes(m.department)){const o=document.createElement('option');o.value=m.department;host.querySelector('#oc-deps').append(o);}}
 const {configureReviewers}=await import('./leadership-review.js');if(isCurrent())await configureReviewers(host.querySelector('.app-card'),sb);
 const q=s=>host.querySelector(s),picker=q('#oc-picker'),profile=q('#oc-profile');picker.onchange=()=>{const p=people.find(p=>p.id===picker.value);profile.reset();if(p){for(const key of ['name','department','role','bio','sort_order'])profile.elements.namedItem(key).value=p[key];profile.elements.published.checked=p.published;}};
 const refresh=async message=>{await adminOC({sb,api,config,host,isCurrent});if(isCurrent())q('#oc-message').textContent=message;};
 submit(profile,async f=>{const p=people.find(p=>p.id===picker.value),file=f.elements.photo.files[0],portrait=file?await uploadPhoto(file,sb,api):p?.portrait||'';const row={name:field(f,'name'),department:field(f,'department'),role:field(f,'role'),bio:field(f,'bio'),portrait,sort_order:Number(field(f,'sort_order')),published:f.elements.published.checked};await data(p?sb.from(roster).update(row).eq('id',p.id).select().single():sb.from(roster).insert(row).select().single());await refresh('Member saved.');});
 submit(q('#oc-grant'),async f=>{await data(sb.rpc('elan_oc_grant',{p_email:field(f,'email'),p_department:field(f,'department'),p_role:field(f,'role')}));await refresh('Organiser assignment saved.');});
 for(const b of host.querySelectorAll('[data-revoke]'))b.onclick=async()=>{if(!confirm('Remove this account’s organiser desk access?'))return;try{await data(sb.from(access).delete().eq('user_id',b.dataset.revoke).select().single());await refresh('Access revoked.');}catch(e){q('#oc-message').textContent=e.message;}};
 submit(q('#oc-task'),async f=>{const u=users.find(u=>u.user_id===field(f,'user_id'));if(!u)throw Error('Choose an organiser.');await data(sb.from(tasks).insert({assigned_to:u.user_id,department:u.department,title:field(f,'title'),brief:field(f,'brief')}).select().single());await refresh('Task assigned.');});
}
